// Framework facts that both bitfab-web and the editor plugins need to agree on.
//
// The full framework registry (labels, detection signals, docs paths, handler
// names) lives in bitfab-plugin-lib/src/flows/frameworks.ts and stays there: it
// is plugin-authoring data with no place in a serverless bundle. What lives here
// is only the narrow subset bitfab-web also has to reason about, so the two can
// no longer disagree silently.
//
// bitfab-plugin-lib asserts its registry against this file (see
// flows/frameworks.test.ts), so adding a framework whose auto-captured model
// span runs through `withSpan` fails there until this set is updated.
/**
 * Framework ids whose AUTO-captured model span runs THROUGH `withSpan`, making
 * it mockable on replay. Every other framework's `auto` spans are observe-only:
 * they are recorded but not wrapped, so replay cannot short-circuit them.
 *
 * Includes agent-facing aliases that are not registry ids in their own right:
 * `vercel` is tagged by the analyzer for the same Vercel AI SDK integration as
 * `vercel-ai-sdk`.
 *
 * The ROOT span is deliberately out of scope: it is never mockable regardless of
 * framework because it starts the replay, a universal rule enforced separately.
 */
export const WITHSPAN_MODEL_FRAMEWORKS = new Set([
    "vercel-ai-sdk",
    "vercel",
]);
/** True when this framework's auto-captured model span is mockable on replay. */
export function hasWithSpanModelCall(framework) {
    return framework !== undefined && WITHSPAN_MODEL_FRAMEWORKS.has(framework);
}
